corrected_code:
const { Kafka } = require('kafkajs');
const kafka = new Kafka({ brokers: [process.env.KAFKA_BROKER] });
const consumer = kafka.consumer({ groupId: 'loyalty-redemption-processor' });

async function runWorker() {
  await consumer.connect();
  await consumer.subscribe({ topic: 'rewards.points.deduct' });

  await consumer.run({
    eachMessage: async ({ message }) => {
      const { loyaltyAccountId, pointsToRedeem, merchantId, initiatorId } = JSON.parse(message.value.toString());

      const member = await knex('loyalty_members')
        .where({ account_id: loyaltyAccountId, user_id: initiatorId })
        .first();
      if (!member) {
        console.error(`Loyalty redemption denied: Account ${loyaltyAccountId} does not belong to ${initiatorId}`);
        return;
      }

      await knex('loyalty_members')
        .where('account_id', loyaltyAccountId)
        .decrement('balance_points', pointsToRedeem);

      await knex('redemption_history').insert({
        account_id: loyaltyAccountId,
        points: pointsToRedeem,
        merchant_id: merchantId,
        created_at: new Date()
      });
    }
  });
}
